package io.knowledgebrain.planning;
import java.util.*;import java.util.concurrent.*;import java.time.*;import org.junit.jupiter.api.*;import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;import org.postgresql.ds.PGSimpleDataSource;import org.springframework.jdbc.core.JdbcTemplate;import org.flywaydb.core.Flyway;import org.springframework.web.server.ResponseStatusException;import static org.junit.jupiter.api.Assertions.*;
@EnabledIfEnvironmentVariable(named="BRAIN_TEST_PLANNING_DATABASE_URL",matches=".+")
class ScheduleStoreIntegrationTest {
 PGSimpleDataSource ds;JdbcTemplate sql;ScheduleStore store;TaskStore tasks;String schema;final UuidV7 ids=new UuidV7(Clock.systemUTC());UUID space,actor;final String trace="b".repeat(32);
 @BeforeEach void init(){ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_PLANNING_DATABASE_URL"));ds.setUser("brain_planning");ds.setPassword(System.getenv("BRAIN_TEST_PLANNING_DATABASE_PASSWORD"));schema="schedule_test_"+UUID.randomUUID().toString().replace("-","");new JdbcTemplate(ds).execute("CREATE SCHEMA "+schema);ds.setCurrentSchema(schema);Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();sql=new JdbcTemplate(ds);store=new ScheduleStore(ds,Clock.systemUTC());tasks=new TaskStore(ds,Clock.systemUTC());space=ids.next();actor=ids.next();}
 @AfterEach void cleanup(){sql.execute("DROP SCHEMA "+schema+" CASCADE");}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 ScheduleStore.Input input(String title,UUID task){return new ScheduleStore.Input(title," preserved\n","2028-11-05T05:30:00Z","2028-11-05T06:30:00Z","America/New_York",task);}
 TaskStore.Task task(UUID scope){return tasks.create(scope,actor,key(),new TaskStore.Input("Task","","NOT_STARTED","2028-11-05",null),trace).task();}
 void status(int n,Runnable work){assertEquals(n,assertThrows(ResponseStatusException.class,work::run).getStatusCode().value());}
 int count(String table){return sql.queryForObject("SELECT count(*) FROM "+table,Integer.class);}
 int events(){return sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype='schedule'",Integer.class);}
 ScheduleRules.Window window(){return ScheduleRules.window("2028-11-05","2028-11-05","America/New_York");}
 @Test void retryHistoryAndPinnedLocalOffsetsSurviveTaskRetirementAndIdentityClaim(){var task=task(space);String key=key();var original=store.create(space,actor,key,input("Schedule",task.taskId()),trace);assertFalse(original.replay());assertEquals("2028-11-05T01:30:00",original.schedule().startsLocal());assertEquals(original.schedule().startsLocal(),original.schedule().endsLocal());assertEquals("-04:00",original.schedule().startsOffset());assertEquals("-05:00",original.schedule().endsOffset());var taskBefore=tasks.get(space,task.taskId());var changed=store.change(space,original.schedule().scheduleId(),ids.next(),1,input("Edited",task.taskId()),false,trace);assertEquals(taskBefore,tasks.get(space,task.taskId()));tasks.change(space,task.taskId(),actor,1,null,true,trace);var taskHistory=tasks.history(space,task.taskId(),Long.MAX_VALUE,5);store.change(space,changed.scheduleId(),actor,2,input("Retained parent",task.taskId()),false,trace);store.change(space,changed.scheduleId(),actor,3,null,true,trace);assertEquals(original.schedule(),store.create(space,ids.next(),key,input("Schedule",task.taskId()),trace).schedule());status(409,()->store.create(space,actor,key,input("Different",task.taskId()),trace));status(404,()->store.get(space,changed.scheduleId()));assertEquals(changed.scheduleId(),store.list(space,"RETIRED",task.taskId().toString(),window(),null,20).items().getFirst().scheduleId());assertEquals(taskHistory,tasks.history(space,task.taskId(),Long.MAX_VALUE,5));assertEquals(1,count("schedule"));assertEquals(4,count("schedule_revision"));assertEquals(4,events());}
 @Test void taskLinksAreSameSpaceAndNewLinksRequireActiveButRetainedEditsAndUnlinkAreAllowed(){var own=task(space);var other=task(actor);for(UUID denied:List.of(other.taskId(),ids.next()))status(404,()->store.create(space,actor,key(),input("Denied",denied),trace));assertEquals(0,count("schedule"));var first=store.create(space,actor,key(),input("Original",own.taskId()),trace).schedule();status(404,()->store.get(actor,first.scheduleId()));status(404,()->store.history(actor,first.scheduleId(),Long.MAX_VALUE,5));status(404,()->store.change(space,first.scheduleId(),actor,1,input("Foreign",other.taskId()),false,trace));tasks.change(space,own.taskId(),actor,1,null,true,trace);status(404,()->store.create(space,actor,key(),input("Retired",own.taskId()),trace));var unlinked=store.change(space,first.scheduleId(),actor,1,input("Unlinked",null),false,trace);assertNull(unlinked.taskId());status(404,()->store.change(space,first.scheduleId(),actor,2,input("Relink",own.taskId()),false,trace));assertThrows(RuntimeException.class,()->sql.update("UPDATE schedule SET task_id=? WHERE schedule_id=?",other.taskId(),first.scheduleId()));assertNull(store.list(space,"ACTIVE","NONE",window(),null,20).items().getFirst().taskId());assertEquals(own.taskId(),store.history(space,first.scheduleId(),Long.MAX_VALUE,5).getLast().snapshot().taskId());}
 @Test void overlapIncludesSpanningIntervalsExcludesTouchingEdgesAndPagesEqualStarts(){var w=window();String start=w.start().toString(),end=w.end().toString();store.create(space,actor,key(),new ScheduleStore.Input("Spanning","",w.start().minusSeconds(1).toString(),w.end().plusSeconds(1).toString(),"UTC",null),trace);store.create(space,actor,key(),new ScheduleStore.Input("Touch before","",w.start().minusSeconds(10).toString(),start,"UTC",null),trace);store.create(space,actor,key(),new ScheduleStore.Input("Touch after","",end,w.end().plusSeconds(10).toString(),"UTC",null),trace);for(int i=0;i<22;i++)store.create(space,actor,key(),input("Equal "+i,null),trace);var a=store.list(space,"ACTIVE","ALL",w,null,20);assertEquals("Spanning",a.items().getFirst().title());assertEquals(20,a.items().size());var b=store.list(space,"ACTIVE","ALL",w,a.nextAfter(),20);assertEquals(3,b.items().size());assertNull(b.nextAfter());var ids=new HashSet<UUID>();a.items().forEach(v->assertTrue(ids.add(v.scheduleId())));b.items().forEach(v->assertTrue(ids.add(v.scheduleId())));assertEquals(23,ids.size());status(400,()->store.list(space,"ACTIVE","NONE",w,a.nextAfter(),20));status(400,()->store.list(actor,"ACTIVE","ALL",w,a.nextAfter(),20));}
 @Test void strongNoopsHistoryAndJdbcInstantCalendarBoundsAreExact(){var first=store.create(space,actor,key(),input("Schedule",null),trace).schedule();assertEquals(first,store.change(space,first.scheduleId(),actor,1,input("Schedule",null),false,trace));status(412,()->store.change(space,first.scheduleId(),actor,2,input("Schedule",null),false,trace));for(int v=1;v<9;v++)store.change(space,first.scheduleId(),actor,v,input("Version "+v,null),false,trace);assertEquals(List.of(9L,8L,7L,6L,5L),store.history(space,first.scheduleId(),Long.MAX_VALUE,5).stream().map(ScheduleStore.Revision::version).toList());assertEquals(List.of(4L,3L,2L,1L),store.history(space,first.scheduleId(),5,5).stream().map(ScheduleStore.Revision::version).toList());ds.setOptions("-c TimeZone=America/New_York");for(String day:List.of("0001-01-01","1582-10-10","9999-12-31")){var v=store.create(space,actor,key(),new ScheduleStore.Input("Calendar","",day+"T12:00:00Z",day+"T13:00:00Z","UTC",null),trace).schedule();assertEquals(OffsetDateTime.parse(v.startsAt()).toInstant(),sql.queryForObject("SELECT starts_at FROM schedule WHERE schedule_id=?",(rs,n)->rs.getObject(1,OffsetDateTime.class).toInstant(),v.scheduleId()));assertEquals(v.scheduleId(),store.list(space,"ACTIVE","ALL",ScheduleRules.window(day,day,"UTC"),null,20).items().getFirst().scheduleId());}}
 @Test void outboxFailureRollsBackAllScheduleMutations(){var v=store.create(space,actor,key(),input("Original",null),trace).schedule();sql.execute("CREATE FUNCTION fail_schedule_outbox() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'controlled outbox failure'; END $$");sql.execute("CREATE TRIGGER fail_schedule_outbox BEFORE INSERT ON outbox_event FOR EACH ROW EXECUTE FUNCTION fail_schedule_outbox()");assertThrows(RuntimeException.class,()->store.create(space,actor,key(),input("Failed",null),trace));assertThrows(RuntimeException.class,()->store.change(space,v.scheduleId(),actor,1,input("Failed",null),false,trace));assertThrows(RuntimeException.class,()->store.change(space,v.scheduleId(),actor,1,null,true,trace));assertEquals(v,store.get(space,v.scheduleId()));assertEquals(1,count("schedule"));assertEquals(1,count("schedule_revision"));assertEquals(1,events());}
 @Test void concurrentCreatesAndEditsHaveOneWinner()throws Exception{String key=key();try(var pool=Executors.newFixedThreadPool(2)){var gate=new CyclicBarrier(2);var a=pool.submit(()->{gate.await();return store.create(space,actor,key,input("Schedule",null),trace);});var b=pool.submit(()->{gate.await();return store.create(space,actor,key,input("Schedule",null),trace);});var one=a.get();var two=b.get();assertEquals(one.schedule(),two.schedule());assertNotEquals(one.replay(),two.replay());var start=new CyclicBarrier(2);var results=new ArrayList<Future<Integer>>();for(int i=0;i<2;i++){final int n=i;results.add(pool.submit(()->{start.await();try{store.change(space,one.schedule().scheduleId(),actor,1,input("Concurrent "+n,null),false,trace);return 200;}catch(ResponseStatusException e){return e.getStatusCode().value();}}));}assertEquals(Set.of(200,412),Set.of(results.get(0).get(),results.get(1).get()));assertEquals(2,count("schedule_revision"));assertEquals(2,events());}}
}
